"use strict";(self.webpackChunkkaminski_portfolio=self.webpackChunkkaminski_portfolio||[]).push([[472],{7472:(e,t,a)=>{a.d(t,{U1:()=>i,en:()=>s});const n=[{slug:"compliance-reviewed-agent",title:"A Compliance-Reviewed AI Agent in Regulated Lending",summary:"Took an AI agent capability from prototype through security, legal, and compliance review into production at a regulated consumer lender.",date:"2026-08-16",tier:"flagship",domain:"Regulated consumer lending",role:"I owned the agent capability end to end: the architecture, the tool surface the model was allowed to call, the evidence design that got it through legal and compliance review, and the approval gates on irreversible actions. Engineering built alongside me; the review strategy, the retention decision, and the control design were mine.",problem:'\n<p>An AI agent that touches a consumer-lending decision is not a model problem. It is an\nevidence problem. The organisation can be entirely satisfied that the agent works and\nstill be unable to ship it, because nobody can produce the artifact a regulator would ask\nfor eighteen months later.</p>\n<p>The moving target made it worse. On May 12, 2025 the CFPB withdrew 67 guidance\ndocuments in a single Federal Register notice &mdash; 8 policy statements, 7 interpretive\nrules, 13 advisory opinions, and 39 others. Two of them were the circulars telling lenders\nhow adverse-action notices had to work when a complex algorithm made the decision. Not one\nword of the underlying duty changed: ECOA still requires a statement of specific reasons,\nand Regulation B still defines what "specific" means.</p>',constraints:["Guidance is the most volatile layer in the stack and the easiest to mistake for the requirement \u2014 the design had to hold when guidance was withdrawn underneath it.","Every agent decision needs a reason string traceable to the component that actually made the decision, not a plausible reconstruction generated after the fact.","Trace retention had to survive the full adverse-action dispute window, not the 30-day default most agent logging ships with.","Irreversible actions could not be model-discretionary.","Review had to satisfy three separate functions \u2014 security, legal, and compliance \u2014 each with its own definition of sufficient evidence."],whatShipped:["An agent capability running in production inside a regulated consumer lender.","A tool surface designed so the model can only take actions the control design permits, with human approval gates on everything irreversible.","A trace and retention design built to a 120-day floor derived from the statutory dispute window rather than from logging defaults.","An eval harness that treats every instruction-file edit as a deploy requiring evidence.","The written record that carried the capability through security, legal, and compliance review."],outcome:[{metric:"120-day trace retention floor",detail:"Derived from the adverse-action dispute window rather than from a logging default. Most agent logging ships at 30 days, which expires before the evidence is ever requested.",source:"/writing/shipping-an-ai-agent-through-compliance-review",sourceLabel:"Read the full write-up"},{metric:"67 guidance documents withdrawn, zero design changes required",detail:"Building against the statute rather than against guidance meant the May 2025 CFPB withdrawal \u2014 which removed both circulars covering algorithmic adverse-action notices \u2014 did not invalidate the control design.",source:"/writing/shipping-an-ai-agent-through-compliance-review",sourceLabel:"Read the full write-up"},{metric:"An approval path where there had not been one",detail:"The capability now has a documented route through security, legal and compliance review that a later one can follow. Before this, no agent capability at the company had been through all three.",source:"/writing/shipping-an-ai-agent-through-compliance-review",sourceLabel:"How the review was framed"},{metric:"Reasons emitted by the deciding component, not reconstructed",detail:"A reason string generated after the fact by a model that did not make the decision is a plausible narrative, not a statement of specific reasons. The tool surface carries the reason out of the component that actually decided.",source:"/writing/shipping-an-ai-agent-through-compliance-review",sourceLabel:"Why the reason string has to come from the decision"},{metric:"Irreversible actions moved behind a human gate",detail:"Anything the agent cannot undo is not model-discretionary. That is a design property of the tool surface rather than a policy asking the model to behave.",source:"/writing/shipping-an-ai-agent-through-compliance-review",sourceLabel:"Read the full write-up"}],outcomePending:"Deployment figures \u2014 rollout scope, volume and measured operational results \u2014 will be added here as they clear publication review. Everything above is publishable now.",artifacts:[{kind:"essay",label:"Shipping an AI Agent Through Compliance Review in Regulated Lending",href:"/writing/shipping-an-ai-agent-through-compliance-review"},{kind:"essay",label:"Statistical Gating for Agent Instruction Changes",href:"/writing/statistical-gating-for-agent-instruction-changes"},{kind:"doc",label:"ECOA / Regulation B \u2014 statement of specific reasons",href:"https://www.consumerfinance.gov/rules-policy/regulations/1002/9/"}],stack:["Python","TypeScript","Model Context Protocol","PostgreSQL","Eval harness"],image:"/images/essays/fig1-retention-floor.png",imageAlt:"Chart of the trace retention floor: a 30-day default log expiring well before the 120-day adverse-action dispute window closes.",body:'\n<h2>By the numbers</h2>\n<p>Retention floor: 120 days. Logging default it replaces: 30 days. Guidance documents\nwithdrawn on 12 May 2025: 67 \u2014 8 policy statements, 7 interpretive rules, 13 advisory\nopinions and 39 others. Circulars covering algorithmic adverse-action notices in that\nwithdrawal: 2. Design changes required as a result: 0. Review functions that had to sign\noff: 3 \u2014 security, legal and compliance.</p>\n\n<h2>Guidance is the layer that moves. Write against the layer that doesn\'t.</h2>\n<p>The single most useful rule from this work: design the agent against the statute and\nagainst the evidence it will have to produce. Guidance is the most volatile layer in the\nstack and the easiest one to mistake for the requirement.</p>\n\n<h2>The review is an evidence problem, not a model problem</h2>\n<p>Security, legal, and compliance were not asking whether the model was good. They were\nasking what artifact exists, where it lives, how long it survives, and who can produce it\nunder request. Reframing the work around that question is what moved it.</p>\n\n<h2>The reason string has to come from the thing that made the decision</h2>\n<p>A reason generated after the fact by a model that did not make the decision is not a\nstatement of specific reasons. It is a plausible narrative. The tool surface had to carry\nthe reason out of the deciding component itself.</p>\n\n<h2>Counting is a compliance control</h2>\n<p>Wherever a control depends on a count, the count is where the bug will be. That is not\na maxim &mdash; it is the failure I went looking for and found.</p>\n<figure>\n<img src="/images/essays/fig2-counter-bug.png" width="920" height="520" loading="lazy"\n     alt="The counter bug: a control whose threshold depends on a count, and the off-by-one that let events past it.">\n<figcaption>The counting defect, drawn out. A control that depends on a count inherits every\nbug in that count &mdash; and the count is rarely the thing anyone reviews.</figcaption>\n</figure>\n\n<p><em>The organisation is described here as "a regulated consumer lender" throughout.\nThe design decisions are mine to discuss; the deployment specifics are not.</em></p>'},{slug:"trade-site-generator",title:"Sites That Differ by Data, Not Code \u2014 a Generator for Trade-Business Websites",summary:"A private template and generator that builds, deploys and verifies a lead-gen website for a trade business from one intake file, with quality gates that refuse a dishonest or thin site.",date:"2026-09-21",tier:"case-study",domain:"Small-business web \xb7 generators",role:"I owned the contract (what five minutes means), the decision records, the media policy, the fabrication rules in the schema, and the verification step that decides when a deploy is allowed to call itself live. The kit, the gates and the two client sites were built with an agent; the rules it builds against are mine.",problem:"\n<p>A small trade business needs a website that says what it sells, where it works, takes a lead and\ncan be found. Built as a project, every site carries the full cost of a project, so most of them\nfreeze on the day the agency invoice clears. The way out is to make sites differ by data, not by\ncode: one kit renders every site, one validated file describes each business, and a fix to the kit\nreaches every client at once.</p>\n<p>The hard part is not the rendering. It is that a generator is tempted to invent the trust content\na real site has (reviews, licence numbers, hours, addresses), and that a thin site is worse than no\nsite once it is measured against a competitor.</p>",constraints:["The generator never fabricates trust content. Reviews and credentials require client-supplied provenance, in the schema, not in a style guide.","Live means verified: every sitemap URL serving 200, no internal link redirecting, and a tokenless lead proven blocked before the scaffold reports success.","Client data reaches the client repository only. The template never carries a database id, an image pack or a site file.","A gate failing on one site is a kit finding, not a per-site waiver."],whatShipped:["A private GitHub template (Astro on Cloudflare Workers with D1 for leads) with nine section components, token-only theming and CSS-first motion.","Six fixtures (lighting, roofing, HVAC, restaurant software, real estate, full) and per-trade image-pack prompts with alt text.","Scaffold and destroy scripts, a structured intake schema, a client-site harvester, a six-category SEO scorer with a reference comparison, and a site CLI.","Quality gates: schema and copy lint, content depth, prose links, axe, overflow, no-JS, reduced motion, focus ring, JS budget, CLS, CTA above the fold, visitor-first UI, local Worker end-to-end, and live verify.","Two client sites generated on 2026-09-21 and 2026-09-22."],outcome:[{metric:"46.5 s from template to verified live site",detail:"Database 2.2 s, bot-check widget 0.3 s, build 1.3 s, repository from template 17.6 s, deploy 11.2 s, verify 13.8 s. Measured 2026-09-21.",source:"/docs/papers/sites-that-differ-by-data-not-code.pdf",sourceLabel:"White paper, section 3"},{metric:"21% \u2192 parity-plus on content depth",detail:"The first launched site had 1,613 words against a 7,722-word reference and was destroyed the same day. Rewritten fixtures carry 10,000 to 12,000 words and score 92+ where the reference scores 75.9.",source:"/docs/papers/sites-that-differ-by-data-not-code.pdf",sourceLabel:"White paper, section 4"},{metric:"Image generation sized to the budget: 43 s hero, 15.2 s everything else",detail:"Four settings measured on 2026-09-21; all judged usable by eye. Nine images run in parallel with harvesting and writing, so the critical path is 200 to 260 s.",source:"/docs/papers/sites-that-differ-by-data-not-code.pdf",sourceLabel:"White paper, section 3"}],outcomePending:"Lead volume from the generated client sites is not yet reported; both sites are days old. The full five-minute run including content generation for a new business is measured for the deploy half only.",artifacts:[{kind:"doc",label:"White paper: Sites That Differ by Data, Not Code (PDF)",href:"/docs/papers/sites-that-differ-by-data-not-code.pdf"},{kind:"essay",label:"Field note: the statute rewrote the product",href:"/writing/the-statute-rewrote-the-product"}],stack:["Astro","TypeScript","Cloudflare Workers","D1","Turnstile","Vitest","Playwright"],image:"/images/papers/fig-time-budget.png",imageAlt:"Bar chart of the five-minute contract by step, measured steps in dark grey and estimates in gold.",body:"\n<h2>By the numbers</h2>\n<p>Template to verified live site: 46.5 s. Template repository created and 101 files pushed: 5.2 s.\nLocal end-to-end (real Worker, local D1, no account): 3.5 s. First site's content vs the reference:\n1,613 vs 7,722 words. Rewritten fixtures: 10,000 to 12,000 words, 45 to 66 validated prose links,\nscore 92+ vs the reference's 75.9. Image generation: 43.1 s for the hero at 1376\xd7768, 15.2 s for\neach of eight others at 1024\xd7576 quantized. Decision records: 12.</p>\n\n<h2>The rule in the schema</h2>\n<p>Trust content requires provenance. A reviews page renders only when client-supplied reviews\nexist. Unsupplied hours, addresses and coordinates are omitted from the page and from the JSON-LD,\nnever inferred. The copy linter refuses specific warranty, insurance and licence claims. Sites\nlaunch honest but thinner until the client supplies the real thing.</p>\n\n<h2>What the first live deploys got wrong</h2>\n<p>Every internal link took a 307, because directory-style output made the platform redirect and\nthe canonical pointed at a redirecting URL. Pages returned 404 briefly while the home page was up,\nbecause assets reach the edge seconds apart. The lead endpoint accepted unverified leads for the\nwidth of one deploy step, because the bot-check secret was set after the code shipped. Each is now\na gate: slashless URLs with a test that fails on any redirecting link, a verify step that polls\nevery sitemap URL, and a secret that ships in the same Worker version as the code with a fail-closed\nendpoint.</p>"},{slug:"transparent-maintenance-os",title:"Transparent Maintenance OS \u2014 One Database, an Agent Desk, and Nothing Ever Deleted",summary:"The internal operating system for a six-person maintenance company: one Postgres database, a static page, twelve serverless functions, and an agent that works its own task queue twice a day.",date:"2026-09-18",tier:"case-study",domain:"Operations \xb7 agent-in-the-loop",role:"I designed the operating model (a task is done once, a process repeats and spawns tasks, a role owns processes), the hub-not-mesh architecture, the agent desk and its hand-over rule, and the attribution design. Thirty decision records are mine; the code was built with agents against them.",problem:'\n<p>A small services company accumulates tools faster than people: a CRM, a field-service system, a\ncalendar, a chat platform, an ad platform. Each is wired to the next by an automation nobody\nremembers, and the question "who owes what, by when" has no single answer.</p>\n<p>The constraint that shaped the answer was cost. The system had to be a thin, zero-hosting layer\nover one database, which forced a rule that turned out to be the design: no tool ever talks to\nanother tool. They talk to the database.</p>',constraints:["Nothing is ever deleted. Soft delete from the UI; every change since 2026-09-11 is in the audit log with before and after values.","The free hosting plan allows twelve serverless functions, and all twelve are in use.","The agent desk never sends email, touches sequences, deletes, or writes to the field-service system, the calendar or the chat platform.","A claim the company makes to a prospect on a call is gated by a column that defaults to false."],whatShipped:["Roles, processes and tasks with a daily spawn job that is idempotent by construction.","Read-only mirrors of the CRM, the field-service system and the ad platform, raw first and typed when read.","Outlook calendar blocks for every dated task, and a real fortnight view that says so when the calendar cannot be read.","A Growth tab: reactivation ranked by recovery, pipeline clocks, an events ledger with drive times, a scorecard against plan, and a weekly report card frozen on Mondays.","The Claude desk: a scheduled routine that works Claude-owned tasks at 9:00 and 14:00 ET, answers into notes, opens pull requests, and hands tasks to the person who holds the system it cannot reach.","A licences panel with per-row renewal windows and a voice gate for the outbound calling agent."],outcome:[{metric:"A 62 KB query string, a 400, and a tab that went down",detail:"2,493 accounts on the board \xd7 24-character ids in one filter. Fixed by paging the mirror in memory, and separately by making the optional lookup unable to fail the page it decorates.",source:"/docs/papers/one-database-many-connectors.pdf",sourceLabel:"White paper, section 4"},{metric:"Attribution by identity: 0 of 585 jobs had a lead source, 72% of customers have a phone",detail:"Ad leads match on the last ten digits of the phone first, then email. Cost metrics are null until their denominator exists, and the funnel names the rung that is holding.",source:"/docs/papers/one-database-many-connectors.pdf",sourceLabel:"White paper, section 5"},{metric:"9 of 10 agent-owned tasks were parked where nobody looks",detail:'The desk now reassigns a task to the person who holds the last system in the chain, with the click path in the notes. "Blocked" means waiting on another task again.',source:"/docs/papers/one-database-many-connectors.pdf",sourceLabel:"White paper, section 6"}],outcomePending:"Revenue, client names, grades and licence numbers are in the system and not published. Paid-advertising lead volume is a funnel with null cost metrics as of 2026-09-14.",artifacts:[{kind:"doc",label:"White paper: One Database, Many Connectors (PDF)",href:"/docs/papers/one-database-many-connectors.pdf"},{kind:"live",label:"Transparent Permits (public product from the same company)",href:"https://transparent-permits.vercel.app"},{kind:"repo",label:"TM Voice (the calling agent)",href:"https://github.com/MAKaminski/tm-voice"}],stack:["Supabase","PostgreSQL","Vercel Functions","TypeScript","Microsoft Graph","Discord","Vercel AI Gateway"],image:"/images/papers/fig-identity.png",imageAlt:"Bar chart: 0 percent of jobs carry a lead source, 72 percent of customers carry a phone, 13 percent carry an email.",body:"\n<h2>By the numbers</h2>\n<p>Accounts on the pipeline board: 2,493. Customers in the field-service mirror: 14,719. Completed\njobs with a lead source over twelve months: 0 of 585. Customers with a phone: 72%; with an email:\n13%. Serverless functions: 12 of 12. Audit log: every change since 2026-09-11. Decision records: 30.\nAgent desk runs: twice a day, six days a week.</p>\n\n<h2>Hub, never mesh</h2>\n<p>The database holds the operating model and a merged copy of what every other system knows.\nInterfaces act on it, connected systems are mirrored into it, connectors move data and hold none.\nA client's owner follows the CRM until someone changes it on the internal board, and then the board\nowns it; one column settles the argument.</p>\n\n<h2>A snapshot is not a move</h2>\n<p>The weekly report card graded A on day one because the scorecard counted the nine snapshot rows\nwritten when stage history began as wins. The first history row per account is a baseline, and a\nmoves column carries that rule into the table. Same data, zero clients won since plan start.</p>"},{slug:"genome-of-games",title:"The Genome of Games \u2014 One Knowledge Base, Four Surfaces",summary:"A build that publishes 1,180 records four ways \u2014 static pages, an interactive graph, a search index, and an MCP server \u2014 in 0.39 seconds with zero dependencies.",date:"2026-08-23",tier:"case-study",domain:"Knowledge graphs \xb7 agent-facing infrastructure",role:"I designed and built the whole pipeline: the source ontology, the build, all four output surfaces, and the MCP tool design. The decision worth copying \u2014 having the MCP server import a build artifact rather than query the site \u2014 is the one I would defend hardest.",problem:"\n<p>A structured knowledge base that has to serve both a search engine and a model usually\nends up serving them from different code paths, and the two drift. The crawler sees one\nanswer, the agent gets another, and nobody notices until someone compares them\nside by side.</p>\n<p>The Genome of Games is an ontology of video game mechanics \u2014 168 mechanics, 618 games,\n394 companies, 4,366 recorded links, spanning 1962 to 2025. What the records describe does\nnot matter. The shape of the problem shows up anywhere one knowledge base has to answer to\nmore than one kind of consumer.</p>",constraints:["An agent and a crawler must never be able to return different answers for the same record.","The build had to stay dependency-free and fast enough to run on every commit.","Agents cannot afford a second hop \u2014 a tool response that returns a stub is a failed call, not a partial one."],whatShipped:["1,245 static HTML pages for crawlers and humans.","An interactive canvas graph of the full ontology.","A 129,037-byte search index powering the site\u2019s own search.","An 8-tool Model Context Protocol server that statically imports the build artifact rather than querying the site."],outcome:[{metric:"1,180 records \u2192 four surfaces in 0.39 seconds",detail:"One command, zero npm dependencies, writing all four outputs from six hand-edited JSON files.",source:"/writing/one-knowledge-base-four-surfaces",sourceLabel:"Read the full write-up"},{metric:"12.7\xd7 read-surface expansion",detail:"1,312,577 bytes of source becomes 16,644,215 bytes of generated read surface \u2014 and every byte of it is disposable.",source:"/writing/one-knowledge-base-four-surfaces",sourceLabel:"Read the full write-up"},{metric:"7,492 links of drift on the one surface the build does not own",detail:"The measured cost of the failure mode the architecture was designed to prevent, observed on the single surface left outside it.",source:"/writing/one-knowledge-base-four-surfaces",sourceLabel:"Read the full write-up"}],artifacts:[{kind:"live",label:"genome-of-games.vercel.app",href:"https://genome-of-games.vercel.app"},{kind:"repo",label:"Source on GitHub",href:"https://github.com/MAKaminski/genome-of-games"},{kind:"essay",label:"One Knowledge Base, Four Surfaces",href:"/writing/one-knowledge-base-four-surfaces"}],stack:["Node.js","Model Context Protocol","Static site generation","Canvas"],image:"/images/projects/genome-four-surfaces.svg",imageAlt:"One build writes four surfaces: six hand-edited JSON files become 1,245 static pages for crawlers, an interactive graph for humans, a 129,037-byte search index, and an 8-tool MCP server for agents \u2014 in 0.39 seconds with zero dependencies.",body:"\n<h2>By the numbers</h2>\n<p>Build time: 0.39 seconds. npm dependencies: 0. Source records: 1,180. Source files: 6\nhand-edited JSON, 1,312,577 bytes. Generated read surface: 16,644,215 bytes, a 12.7\xd7\nexpansion. Static HTML pages: 1,245. Search index: 129,037 bytes. MCP tools: 8. Ontology:\n168 mechanics, 618 games, 394 companies, 4,366 recorded links, 1962 to 2025. Drift on the\none surface the build does not own: 7,492 links.</p>\n\n<h2>The decision that sounds like a downgrade</h2>\n<p>The MCP server does not query the site and does not read the source data. It statically\nimports a 1.9 MB index that the build wrote. There is exactly one place where slugs,\nlineage, and adoption edges get joined, so an agent and a crawler cannot come back with\ndifferent answers.</p>\n\n<h2>Tool design for a consumer with no second hop</h2>\n<p>A human who gets a stub clicks through. An agent that gets a stub has burned a call. So\neach tool returns the whole useful object, and the tool descriptions spend their token\nbudget on when to call the tool rather than on what the tool contains.</p>"},{slug:"dealer-gamma-pipeline",title:"A Dealer-Gamma Pipeline That Moved on Zero Trades",summary:"A dealer-gamma pipeline that recomputes option-chain levels every fifteen minutes \u2014 and the append-only write that caught it moving levels on a closed market.",date:"2026-08-17",tier:"case-study",domain:"Market structure \xb7 data pipelines",role:"I built the pipeline and the study it writes, and I found the defect. The fix was not a code change so much as an instrumentation decision: the system was already wrong, and the only reason it became visible is that I stopped letting it overwrite its own evidence.",problem:"\n<p>The pipeline recomputes call wall, put wall, and gamma flip off the live option chain\nand writes a thinkScript study the chart reloads. The first version did exactly one write:\ncompute, overwrite, reload.</p>\n<p>It looked correct for weeks. An overwritten file has no history to argue with. The\nstudy fires an alert when price crosses the gamma flip \u2014 so if the flip is silently\nre-estimating while price stands still, the alert is firing on its own arithmetic, and\nnone of it is reconstructable after the fact.</p>",constraints:["The levels feed an alert, so a silent re-estimate is indistinguishable from a real crossing.","The original design destroyed the only evidence that could have shown the problem.","Any fix had to run inside the existing fifteen-minute cadence without adding a dependency."],whatShipped:["A dealer-gamma pipeline running 33 times a day across seven underlyings at a fifteen-minute cadence.","A generated thinkScript study the chart reloads in place.","A per-symbol append-only CSV written alongside the study \u2014 the change that made the defect visible."],outcome:[{metric:"Gamma flip walked 718.3 \u2192 722.2 with spot pinned at 717.12",detail:"Eight consecutive writes on a closed market: put wall 710 \u2192 700, net GEX 598 \u2192 626 \u2192 611, and not a single share traded. The chain re-fit and the levels moved on their own.",source:"/clips#levels-that-move-when-nothing-trades",sourceLabel:"Watch the clip and read the transcript"},{metric:"33 runs per day across 7 underlyings",detail:"The cadence that made the drift frequent enough to catch once there was an append-only record to catch it in.",source:"/clips#levels-that-move-when-nothing-trades",sourceLabel:"Watch the clip and read the transcript"}],artifacts:[{kind:"clip",label:"Zero trades, and the level still moved",href:"/clips#levels-that-move-when-nothing-trades"}],stack:["Python","thinkScript","Option-chain data","CSV"],image:"/videos/levels-that-move-when-nothing-trades-poster.jpg",imageAlt:"Poster frame from the field clip: the QQQ gamma flip walking upward across consecutive writes while spot price stays fixed.",body:"\n<h2>By the numbers</h2>\n<p>Runs per day: 33. Underlyings: 7. Cadence: every 15 minutes. Consecutive writes over\nwhich the levels moved: 8. Spot price across all 8: 717.12, unchanged. Gamma flip: 718.3 \u2192\n719.5 \u2192 720.0 \u2192 722.2, a 3.9-point walk. Put wall: 710 \u2192 700. Net GEX: 598 \u2192 626 \u2192 611.\nShares traded in that window: 0.</p>\n\n<h2>The fix was one more write</h2>\n<p>Not a rewrite &mdash; an addition. A per-symbol append-only CSV next to the study. The\ncomputation did not change at all. What changed is that the system could no longer destroy\nthe record of what it had done, and eight rows later the defect was obvious.</p>\n\n<h2>Why this generalises</h2>\n<p>Any process that overwrites its own output is a process whose failures are\nunreconstructable by construction. That is worth more than the specific finding: the bug\nhad been running for weeks in a system I looked at daily.</p>"}],i=e=>n.find(t=>t.slug===e),s=()=>n.slice().sort((e,t)=>Number("flagship"===t.tier)-Number("flagship"===e.tier)||t.date.localeCompare(e.date))}}]);